<?php
declare(strict_types=1);
require __DIR__ . '/_bootstrap.php';
ob_start();
register_shutdown_function(static function():void{global $coupon,$id;$html=(string)ob_get_clean();if($coupon){$panel='<div class="card-soft p-4 mt-3"><div class="d-flex justify-content-between align-items-center mb-3"><h6 class="mb-0">Send or print</h6><a class="btn btn-outline-secondary" target="_blank" href="coupon_print.php?id='.(int)$id.'">Print / PDF</a></div><form method="post" class="row g-2"><input type="hidden" name="action" value="send_test">'.csrf_input().'<input type="hidden" name="id" value="'.(int)$id.'"><div class="col-md-8"><label class="form-label">Email coupon</label><input class="form-control" type="email" required name="test_email" value="'.h((string)($coupon['recipient_email']??'')).'" placeholder="Recipient email"></div><div class="col-md-4 d-flex align-items-end"><button class="btn btn-outline-success w-100">Send coupon email</button></div></form></div>';$html=str_replace('</main>',$panel.'</main>',$html);}echo $html;});

if (!in_array(strtolower((string)($currentUser['role'] ?? '')), ['superadmin','developer'], true)) { http_response_code(403); exit('Coupon management is restricted to super administrators.'); }
ensureCouponTables($pdo);
$siteSettings=getSiteSettings($pdo);
$events=fetchEvents($pdo,false);
$pastEvents=array_values(array_filter($events,static fn(array $event):bool=>(string)($event['event_date']??'')!==''&&(string)$event['event_date']<date('Y-m-d')));
$id=max(0,(int)($_GET['id']??$_POST['id']??0));
$returnTo=trim((string)($_REQUEST['return_to']??'coupons.php'));
if (!preg_match('#^coupons\.php(?:\?[^\r\n]*)?$#',$returnTo)) $returnTo='coupons.php';
$coupon=null;
if($id){$stmt=$pdo->prepare('SELECT * FROM coupons WHERE id=:id');$stmt->execute([':id'=>$id]);$coupon=$stmt->fetch()?:null;if(!$coupon){http_response_code(404);exit('Coupon not found.');}}

if($_SERVER['REQUEST_METHOD']==='POST'&&($_POST['action']??'')==='send_test'&&$coupon){$email=trim((string)($_POST['test_email']??''));if(!filter_var($email,FILTER_VALIDATE_EMAIL))$alerts[]=['type'=>'danger','message'=>'Enter a valid test email address.'];else{$link=rtrim(email_public_asset_url('/',$siteSettings),'/').'/basket?coupon='.rawurlencode((string)$coupon['code']);$inner='<h2>'.h((string)$coupon['title']).'</h2><p>Coupon code: <strong>'.h((string)$coupon['code']).'</strong></p><p>Value: '.h(format_price($coupon['amount'])).'</p><p><a href="'.h($link).'">Open your basket and apply this coupon</a></p>';$ok=send_logged_email($pdo,$email,'Your ILDRA coupon: '.(string)$coupon['code'],wrap_user_email_html($siteSettings,getEmailSettings($pdo),$inner),strip_tags($inner),['type'=>'coupon','send_type'=>1,'coupon_id'=>$id]);coupon_log($pdo,$id,(int)$currentUser['id'],$ok?'emailed':'email_failed',$email);$alerts[]=['type'=>$ok?'success':'warning','message'=>$ok?'Coupon email sent.':'Coupon email could not be sent.'];}}elseif($_SERVER['REQUEST_METHOD']==='POST'){
    $type=(string)($_POST['coupon_type']??'manual');
    $from=trim((string)($_POST['valid_from']??''));$until=trim((string)($_POST['valid_until']??''));
    $issuedEventId=(int)($_POST['issued_event_id']??0);
    if($type==='ride_helper'){
        $rideDate='';foreach($events as$event)if((int)$event['id']===$issuedEventId){$rideDate=(string)($event['event_date']??'');break;}
        if($rideDate==='')$alerts[]=['type'=>'danger','message'=>'Select the past event the helper supported.'];else{$from=$rideDate.' 00:00:00';$until=substr($rideDate,0,4).'-12-31 23:59:59';}
        $_POST['amount']=$siteSettings['ride_helper_coupon_value']??0;$_POST['title']='Ride Helper Coupon';
    }
    if(!$alerts){
        if($coupon){
            $stmt=$pdo->prepare("UPDATE coupons SET coupon_type=:type,code=:code,title=:title,message_html=:message,terms_html=:terms,amount=:amount,valid_from=:from_date,valid_until=:until_date,event_id=:event_id,usage_limit=:usage_limit,per_person_limit=:person_limit,recipient_email=:recipient,issued_event_id=:issued_event,updated_at=NOW() WHERE id=:id");
            try{$stmt->execute([':type'=>$type,':code'=>strtoupper(trim((string)$_POST['code'])),':title'=>trim((string)$_POST['title']),':message'=>trim((string)$_POST['message_html'])?:null,':terms'=>trim((string)$_POST['terms_html'])?:null,':amount'=>round(max(0,price_to_number($_POST['amount']??0)),2),':from_date'=>$from,':until_date'=>$until,':event_id'=>(int)($_POST['event_id']??0)?:null,':usage_limit'=>$type==='marketing'?max(1,(int)($_POST['usage_limit']??1)):1,':person_limit'=>$type==='marketing'?max(0,(int)($_POST['per_person_limit']??1)):0,':recipient'=>trim((string)$_POST['recipient_email'])?:null,':issued_event'=>$issuedEventId?:null,':id'=>$id]);coupon_log($pdo,$id,(int)$currentUser['id'],'updated');$_SESSION['flash_success']='Coupon updated.';header('Location: '.$returnTo);exit;}catch(Throwable $e){$alerts[]=['type'=>'danger','message'=>'Coupon could not be updated. Check the code is unique and values are valid.'];}
        }else{
            $payload=['coupon_type'=>$type,'code'=>$_POST['code']??'','title'=>$_POST['title']??'','message_html'=>$_POST['message_html']??'','terms_html'=>$_POST['terms_html']??'','amount'=>$_POST['amount']??0,'valid_from'=>$from,'valid_until'=>$until,'event_id'=>$_POST['event_id']??0,'usage_limit'=>$_POST['usage_limit']??1,'per_person_limit'=>$_POST['per_person_limit']??1,'recipient_email'=>$_POST['recipient_email']??'','issued_event_id'=>$issuedEventId];
            $newId=coupon_create($pdo,$payload,(int)$currentUser['id'],$alerts);if($newId){$_SESSION['flash_success']='Coupon created.';header('Location: '.$returnTo);exit;}
        }
    }
}
$value=static function(string $key,string $default='')use($coupon):string{$raw=(string)($_POST[$key]??$coupon[$key]??$default);if(in_array($key,['valid_from','valid_until'],true)&&str_contains($raw,' '))$raw=str_replace(' ','T',substr($raw,0,16));return h($raw);};
$type=(string)($_POST['coupon_type']??$coupon['coupon_type']??'manual');
admin_layout_start($coupon?'Edit coupon':'Add coupon','coupons');
?>
<div class="d-flex justify-content-between align-items-center mb-3"><div><div class="small text-muted">Coupon management</div><h5 class="mb-0"><?php echo $coupon?'Edit coupon':'Add coupon'; ?></h5></div><a class="btn btn-outline-secondary" href="<?php echo h($returnTo); ?>">Return to list</a></div>
<div class="card-soft p-4"><form method="post" class="row g-3"><input type="hidden" name="id" value="<?php echo $id; ?>"><input type="hidden" name="return_to" value="<?php echo h($returnTo); ?>"><div class="col-md-3"><label class="form-label">Type</label><select class="form-select" name="coupon_type" id="coupon-type"><option value="manual" <?php echo $type==='manual'?'selected':''; ?>>Manual single use</option><option value="ride_helper" <?php echo $type==='ride_helper'?'selected':''; ?>>Ride Helper single use</option><option value="marketing" <?php echo $type==='marketing'?'selected':''; ?>>Marketing multi use</option></select></div><div class="col-md-3 coupon-value"><label class="form-label">Value (£)</label><input class="form-control" name="amount" required type="number" min="0.01" step="0.01" value="<?php echo $value('amount',(string)($siteSettings['ride_helper_coupon_value']??'')); ?>"></div><div class="col-md-3"><label class="form-label">Code</label><input class="form-control text-uppercase" name="code" maxlength="32" value="<?php echo $value('code'); ?>" placeholder="Leave blank to generate"></div><div class="col-md-3"><label class="form-label">Recipient email</label><input class="form-control" type="email" name="recipient_email" value="<?php echo $value('recipient_email'); ?>"></div><div class="col-md-6 coupon-title"><label class="form-label">Title / text</label><input class="form-control" required name="title" value="<?php echo $value('title'); ?>"></div><div class="col-md-3 coupon-validity"><label class="form-label">Valid from</label><input class="form-control" type="datetime-local" name="valid_from" value="<?php echo $value('valid_from',date('Y-m-d').'T00:00'); ?>"></div><div class="col-md-3 coupon-validity"><label class="form-label">Valid until</label><input class="form-control" type="datetime-local" name="valid_until" value="<?php echo $value('valid_until',date('Y').'-12-31T23:59'); ?>"></div><div class="col-md-4"><label class="form-label">Only for this event</label><select class="form-select" name="event_id"><option value="0">Any eligible purchase</option><?php foreach($events as$event):?><option value="<?php echo(int)$event['id'];?>" <?php echo (int)($_POST['event_id']??$coupon['event_id']??0)===(int)$event['id']?'selected':''; ?>><?php echo h((string)$event['title'].' · '.(string)$event['event_date']);?></option><?php endforeach;?></select></div><div class="col-md-2 marketing-only"><label class="form-label">Marketing uses</label><input class="form-control" name="usage_limit" type="number" min="1" value="<?php echo $value('usage_limit','1'); ?>"></div><div class="col-md-2 marketing-only"><label class="form-label">Per person</label><input class="form-control" name="per_person_limit" type="number" min="0" value="<?php echo $value('per_person_limit','1'); ?>"></div><div class="col-md-4 ride-helper-only"><label class="form-label">Ride Helper event</label><select class="form-select" name="issued_event_id"><option value="0">Select past event…</option><?php foreach($pastEvents as$event):?><option value="<?php echo(int)$event['id'];?>" <?php echo (int)($_POST['issued_event_id']??$coupon['issued_event_id']??0)===(int)$event['id']?'selected':''; ?>><?php echo h((string)$event['title'].' · '.(string)$event['event_date']);?></option><?php endforeach;?></select></div><div class="col-12"><label class="form-label">Coupon wording</label><textarea class="form-control wysiwyg-field" rows="4" name="message_html"><?php echo $value('message_html'); ?></textarea></div><div class="col-12"><label class="form-label">Terms placeholder</label><textarea class="form-control wysiwyg-field" rows="3" name="terms_html"><?php echo $value('terms_html'); ?></textarea></div><div class="col-12"><button class="btn btn-success"><?php echo $coupon?'Save changes':'Create coupon'; ?></button></div></form></div>
<?php render_tinymce_bootstrap(); ?><script>if(window.tinymce)tinymce.init(window.ildraTinyMceConfig({selector:'textarea.wysiwyg-field'}));(()=>{const type=document.getElementById('coupon-type'),sync=()=>{const ride=type.value==='ride_helper',marketing=type.value==='marketing';document.querySelectorAll('.ride-helper-only').forEach(el=>{el.hidden=!ride;el.querySelector('select').required=ride;});document.querySelectorAll('.marketing-only').forEach(el=>el.hidden=!marketing);document.querySelectorAll('.coupon-validity,.coupon-value,.coupon-title').forEach(el=>el.hidden=ride);document.querySelector('[name=title]').required=!ride;document.querySelector('[name=amount]').required=!ride;};type.addEventListener('change',sync);sync();})();</script><?php admin_layout_end();
